const input = $input.first().json;
const expectedInternal=String((typeof $env!=='undefined'?$env.INTERNAL_WEBHOOK_TOKEN:'')||'').trim();
const receivedInternal=String(input.headers?.['x-smart-classroom-internal']||'').trim();
if(expectedInternal&&receivedInternal!==expectedInternal)throw new Error('INTERNAL_WEBHOOK_UNAUTHORIZED');
const body = input.body ?? input;
const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v);
try {
  if (!isObject(body)) throw new Error('Body phải là JSON object.');
  const x = isObject(body.incident_candidate) ? body.incident_candidate : body;
  const aliases = {
    HOT: 'HIGH_TEMPERATURE', TEMPERATURE: 'HIGH_TEMPERATURE',
    HUMIDITY: 'HIGH_HUMIDITY', CO2: 'HIGH_CO2', CO2_HIGH: 'HIGH_CO2',
    POWER_WASTE: 'ENERGY_WASTE', DOOR_AFTER_HOURS: 'AFTER_HOURS_DOOR',
    OFFLINE: 'DEVICE_OFFLINE', INVALID_TELEMETRY: 'INVALID_PAYLOAD',
    COMMAND_FAILED: 'COMMAND_FAILURE', COMMAND_TIMEOUT: 'COMMAND_FAILURE',
    LATE_ACK: 'COMMAND_FAILURE'
  };
  const rawType = String(x.type || '').trim().toUpperCase().replace(/[\s-]+/g, '_');
  const type = aliases[rawType] || rawType;
  const types = ['SENSOR_ANOMALY', 'HIGH_TEMPERATURE', 'HIGH_HUMIDITY', 'HIGH_CO2', 'ENERGY_WASTE', 'AFTER_HOURS_DOOR', 'DEVICE_OFFLINE', 'COMMAND_FAILURE', 'INVALID_PAYLOAD', 'CUSTOM'];
  if (!types.includes(type)) throw new Error('Loại sự cố không hợp lệ: ' + type);
  const rawSeverity = String(x.severity || 'WARNING').trim().toUpperCase();
  const severity = ({LOW: 'INFO', MINOR: 'INFO', MEDIUM: 'WARNING', HIGH: 'CRITICAL', SEVERE: 'CRITICAL'})[rawSeverity] || rawSeverity;
  if (!['INFO', 'WARNING', 'CRITICAL'].includes(severity)) throw new Error('Severity không hợp lệ.');
  function requiredText(value, name, max) {
    if (typeof value !== 'string' || !value.trim() || value.trim().length > max) throw new Error(name + ' phải là chuỗi không rỗng, tối đa ' + max + ' ký tự.');
    return value.trim();
  }
  const event_key = requiredText(x.event_key, 'event_key', 250);
  const dedup_key = requiredText(x.dedup_key, 'dedup_key', 180);
  const device = x.device_id ?? x.device_code;
  const room = x.room ?? x.room_code;
  if (!device && !room) throw new Error('Cần device_id hoặc room.');
  if (x.recovered !== undefined && typeof x.recovered !== 'boolean') throw new Error('recovered phải là boolean.');
  const observed_at = x.observed_at;
  if (typeof observed_at !== 'string' || !/^\d{4}-\d\d-\d\dT.*(?:Z|[+-]\d\d:\d\d)$/.test(observed_at) || !Number.isFinite(Date.parse(observed_at))) throw new Error('observed_at phải là ISO timestamp có múi giờ.');
  if (Date.parse(observed_at) > Date.now() + 60000) throw new Error('observed_at vượt quá 60 giây trong tương lai.');
  const details = x.details ?? x.evidence ?? {};
  if (!isObject(details)) throw new Error('details/evidence phải là object.');
  const payload = {
    type, severity,
    title: requiredText(x.title ?? x.reason ?? type, 'title', 250),
    event_key, dedup_key,
    recovered: x.recovered === true,
    observed_at: new Date(observed_at).toISOString(),
    details
  };
  if (device) payload.device_id = requiredText(device, 'device_id', 100);
  if (room) payload.room = requiredText(room, 'room', 100);
  return [{json: {valid: true, payload}}];
} catch (error) {
  return [{json: {
    valid: false,
    http_status: 400,
    response_body: {
      workflow_version: 'V3',
      ok: false,
      error_type: 'INVALID_CANDIDATE',
      message: error.message
    }
  }}];
}

const response = $input.first().json;
const candidate = $('Normalize Candidate').first().json.payload;
function fail(code, type, message) {
  return [{json: {
    http_status: code,
    response_body: {
      workflow_version: 'V3',
      ok: false,
      event_key: candidate.event_key,
      error_type: type,
      message
    }
  }}];
}
if (response.error || !Number.isInteger(response.statusCode)) return fail(503, 'BACKEND_UNAVAILABLE', 'Chưa xác nhận được kết quả lưu sự kiện. Khi thử lại, giữ nguyên event_key và nội dung.');
let result = response.body;
if (typeof result === 'string') {
  try { result = JSON.parse(result); } catch { result = null; }
}
if (response.statusCode < 200 || response.statusCode >= 300) {
  const code = response.statusCode >= 400 && response.statusCode <= 599 ? response.statusCode : 502;
  const message = Array.isArray(result?.message) ? result.message.join(' | ') : typeof result?.message === 'string' ? result.message : 'Backend từ chối sự kiện.';
  return fail(code, 'BACKEND_REJECTED', message);
}
const actions = ['OPENED', 'UPDATED', 'RESOLVED', 'IGNORED_STALE', 'NO_OPEN_INCIDENT'];
if (result?.ok !== true || result.event_key !== candidate.event_key || !actions.includes(result.event_action)) return fail(502, 'INVALID_BACKEND_RESPONSE', 'Backend response không đúng contract incidents V3.');
if (['OPENED', 'UPDATED', 'RESOLVED'].includes(result.event_action) && !result.incident_id) return fail(502, 'INVALID_BACKEND_RESPONSE', 'Backend thiếu incident_id.');
return [{json: {
  http_status: 200,
  response_body: {
    ...result,
    workflow_version: 'V3',
    processed_by: 'WF10',
    message: result.event_duplicate === true
      ? 'Sự kiện đã được xử lý trước đó. Đây là kết quả đã lưu, không phải truy vấn trạng thái sự cố mới nhất.'
      : 'Backend đã xử lý sự kiện. Xem event_action để biết kết quả.'
  }
}}];
